-- =====================
-- MODES
-- =====================
MODES={
 {name="10 PIN", pins=10, type="normal"},
 {name="DUCKPIN", pins=10, type="normal"},
 {name="CANDLEPIN", pins=10, type="normal"},
 {name="HOLY 9 PIN", pins=9, type="normal"},
 {name="TEXAS 9 PIN", pins=9, type="texas"},
 {name="5 PIN", pins=5, type="five"}
}

-- Rolls per frame for each mode
ROLLS_PER_FRAME={2,3,3,1,2,3} -- Holy Roman 9-pin = 1 roll

-- =====================
-- PIN LAYOUTS (map coordinates)
-- =====================
PIN_LAYOUTS={
 [1]={{11,1},{13,1},{15,1},{17,1},{12,2},{14,2},{16,2},{13,3},{15,3},{14,4}},
 [2]={{11,1},{13,1},{15,1},{17,1},{12,2},{14,2},{16,2},{13,3},{15,3},{14,4}},
 [3]={{11,1},{13,1},{15,1},{17,1},{12,2},{14,2},{16,2},{13,3},{15,3},{14,4}},
 [4]={{14,1},{13,2},{12,3},{13,4},{14,3},{14,5},{15,4},{16,3},{15,2}},
 [5]={{14,1},{13,2},{12,3},{13,4},{14,3},{14,5},{15,4},{16,3},{15,2}}, -- TEXAS 9 PIN
 [6]={{14,3},{13,2},{15,2},{12,1},{16,1}} -- 5 PIN
}

-- =====================
-- 5-PIN VALUES
-- =====================
FIVE_PIN_VALUES={5,3,3,2,2}

-- =====================
-- TEXAS RED PIN
-- =====================
TEXAS_RED_PIN_INDEX=5

-- =====================
-- SPRITES
-- =====================
PIN_SPRITES={ [1]=256,[2]=259,[3]=258,[4]=263,[5]=256,[6]=256 }
RED_PIN_SPR=257
BALL_SPRITES={ [1]=260,[2]=261,[3]=262,[4]=261,[5]=260,[6]=261 }

-- =====================
-- GAME STATE
-- =====================
mode=1
frame=1
roll=1
ball_map_x=14
ball_map_y=16
ball_x = ball_map_x*8
ball_y = ball_map_y*8
ball_moving=false
ball_speed=1.5 -- smoother animation
pins={}
pins_left=MODES[mode].pins
frame_score=0
last_roll=0
hit_timer=0
show_title=true

-- =====================
-- INIT PINS
-- =====================
function init_pins()
 pins={}
 for i=1,#PIN_LAYOUTS[mode] do
  pins[i]=true
 end
end
init_pins()

-- =====================
-- RESET FRAME
-- =====================
function reset_frame()
 frame=frame+1
 roll=1
 frame_score=0
 pins_left=MODES[mode].pins
 init_pins()
 ball_moving=false
 ball_y=ball_map_y*8
end

-- =====================
-- REMOVE PINS + SCORE
-- =====================
function remove_pins(count)
 local standing={}
 for i=1,#pins do
  if pins[i] then table.insert(standing,i) end
 end

 -- TEXAS 9-PIN special
 if MODES[mode].type=="texas" and count==8 then
  local removed=0
  for i=1,#pins do
   if i~=TEXAS_RED_PIN_INDEX and pins[i] and removed<8 then
    pins[i]=false
    removed=removed+1
   end
  end
  return
 end

 -- 5-PIN scoring
 if MODES[mode].type=="five" then
  local removed=0
  while removed<count and #standing>0 do
   local r=math.random(#standing)
   local pin=standing[r]
   pins[pin]=false
   frame_score=frame_score+FIVE_PIN_VALUES[pin]
   table.remove(standing,r)
   removed=removed+1
  end
  return
 end

 -- 10, duck, candle, holy roman 9 pin MODES
 for i=1,count do
  if #standing==0 then break end
  local r=math.random(#standing)
  local pin=standing[r]
  pins[pin]=false
  frame_score=frame_score+1
  table.remove(standing,r)
 end
end

-- =====================
-- LAUNCH BALL
-- =====================
function launch_ball()
 if not ball_moving then
  ball_moving=true
  ball_y=ball_map_y*8
 end
end

-- =====================
-- UPDATE BALL & COLLISION
-- =====================
function update_ball()
 if not ball_moving then return end

 -- move ball down
 ball_y = ball_y - ball_speed

 local layout = PIN_LAYOUTS[mode]

 -- COLLISION WITH PINS
 for i,p in ipairs(layout) do
  if pins[i] then
   local pin_x = p[1]*8 - 4
   local pin_y = p[2]*8 - 4
   local radius = 10
   if mode==5 then radius=12 end
   if mode==4 then radius=11 end
   if math.abs(ball_x - pin_x)<radius and math.abs(ball_y - pin_y)<radius then
    pins[i]=false
    if MODES[mode].type=="five" then
     frame_score=frame_score+FIVE_PIN_VALUES[i]
    else
     frame_score=frame_score+1
    end
   end
  end
 end

 -- END ROLL AFTER BALL PASSES ALL PINS
 local max_pin_y=0
 for i,p in ipairs(layout) do
  if pins[i] then
    local py=p[2]*8 - 4
    if py>max_pin_y then max_pin_y=py end
  end
 end

 if ball_y<=max_pin_y then
  local m=MODES[mode]
  local knocked=0

  if m.type=="normal" or m.type=="five" then
   if math.random()<0.20 then knocked=pins_left end
  elseif m.type=="texas" then
   local r=math.random()
   if r<0.04 then knocked=9
   elseif r<0.05 then knocked=8 end
  end

  if knocked>0 then remove_pins(knocked) end

  pins_left=0
  last_roll=knocked
  roll=roll+1
  hit_timer=10
  ball_moving=false
  ball_y=ball_map_y*8

  -- RESET FRAME BASED ON MODE-SPECIFIC ROLLS
  if roll>ROLLS_PER_FRAME[mode] then
    reset_frame()
  end
 end
end

-- =====================
-- DRAW PINS
-- =====================
function draw_pins()
 local layout=PIN_LAYOUTS[mode]
 for i,p in ipairs(layout) do
  if pins[i] then
   local s=PIN_SPRITES[mode]
   if mode==5 and i==TEXAS_RED_PIN_INDEX then s=RED_PIN_SPR end
   spr(s,p[1]*8,p[2]*8,0)
  end
 end
end

-- =====================
-- TITLE SCREEN
-- =====================
function draw_title()
 cls(0)
 print("Copyright (C) 2025 Daniel",0,10,12,false,1,true)
 print("Hanrahan Tools and Games",0,20,12,false,1,true)
 print("SPDX-License-Identifier: GPL-3.0-or-later",0,30,12,false,1,true)
 print("A copy of the GNU General Public License is",0,40,12,false,1,true)
 print("included in the file COPYING; if not, see",0,50,12,false,1,true)
 print("<https://www.gnu.org/licenses/>.",0,60,12,false,1,true)
 print("Information just about the stuff in this",0,70,12,false,1,true)
 print("software not covered by the GNU General Public License version 3: This work is",0,80,12,false,1,true)
 print("licensed under Attribution-ShareAlike 4.0 International",0,90,12,false,1,true)
 print("PRESS Z TO START",80,120,12,false,1,true)
end

-- =====================
-- MAIN LOOP
-- =====================
function TIC()
 if show_title then
   draw_title()
   if btnp(4) then show_title=false end
   return
 end

 cls(0)
 -- DRAW LANE
 map(0,0,30,17,0,0)

 -- MOVE BALL (locked while moving)
 if not ball_moving then
    if btn(2) then ball_x=ball_x-1 end
    if btn(3) then ball_x=ball_x+1 end
    ball_x=math.max(20,math.min(220,ball_x))
 end

 -- LAUNCH BALL
 if btnp(4) then launch_ball() end

 -- UPDATE BALL
 update_ball()

 -- SWITCH MODE
 if btnp(5) then
  mode=mode%#MODES+1
  frame=1
  roll=1
  pins_left=MODES[mode].pins
  frame_score=0
  init_pins()
  ball_moving=false
  ball_y=ball_map_y*8
 end

 -- DRAW BALL
 spr(BALL_SPRITES[mode],ball_x,ball_y)

 -- DRAW PINS
 draw_pins()

 -- UI
 print("MODE: "..MODES[mode].name,0,10,12)
 print("FRAME: "..frame,0,20,12)
 print("ROLL: "..roll,0,30,12)
 print("PINS LEFT: "..pins_left,0,40,12)
 print("FRAME SCORE: "..frame_score,0,50,12)
 print("LAST ROLL: "..last_roll,0,60,12)
 print("TABULATE SCORE MANUALLY",0,120,12,false,1,true)
end

